#include <iostream>
#include <stack>
#include <string>

int main() {
    std::string line;
    if (!std::getline(std::cin, line)) return 1;
    if (line.size() > 1000) return 1;
    std::stack<char> pending;
    for (char ch : line) {
        if (ch == '(') {
            pending.push(ch);
        } else if (ch == ')') {
            if (pending.empty()) {
                std::cout << "no" << std::endl;
                return 0;
            }
            pending.pop();
        } else {
            return 1;
        }
    }
    std::cout << (pending.empty() ? "yes" : "no") << std::endl;
    return 0;
}
